package io.github.jesterportfolio.hearth.phone;

import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

final class PhoneTelemetryTest {
    private static PhoneTelemetry.Timing phase(PhoneTelemetry.Snapshot snapshot,PhoneTelemetry.Phase phase){return snapshot.timings().stream().filter(t->t.phase()==phase).findFirst().orElseThrow();}
    @Test void stagesAndTotalUseOneClockAndDoNotDoubleCountCompletion(){
        var clock=new AtomicLong();var metrics=new PhoneTelemetry(clock::get);var flow=metrics.begin();flow.start(PhoneTelemetry.Phase.PREFLIGHT);clock.set(10_000_000);flow.finish(PhoneTelemetry.Phase.PREFLIGHT);flow.start(PhoneTelemetry.Phase.ANSWER_WAIT);clock.set(30_000_000);flow.finish(PhoneTelemetry.Phase.ANSWER_WAIT);flow.start(PhoneTelemetry.Phase.VALIDATION);clock.set(45_000_000);flow.complete(PhoneTelemetry.Outcome.ACCEPTED);flow.complete(PhoneTelemetry.Outcome.CLOSED);flow.finish(PhoneTelemetry.Phase.ANSWER_WAIT);
        var s=metrics.snapshot();assertEquals(45,phase(s,PhoneTelemetry.Phase.TOTAL).totalMillis());assertEquals(10,phase(s,PhoneTelemetry.Phase.PREFLIGHT).totalMillis());assertEquals(20,phase(s,PhoneTelemetry.Phase.ANSWER_WAIT).totalMillis());assertEquals(15,phase(s,PhoneTelemetry.Phase.VALIDATION).totalMillis());assertEquals(1,s.outcomes().get(PhoneTelemetry.Outcome.ACCEPTED));assertEquals(0,s.outcomes().get(PhoneTelemetry.Outcome.CLOSED));assertTrue(s.timings().stream().allMatch(t->t.active()==0));
    }
    @Test void snapshotsAreImmutableAndContainNoPrivateContentOrCallerIdentity(){var m=new PhoneTelemetry();var flow=m.begin();flow.complete(PhoneTelemetry.Outcome.PREFLIGHT_REJECTED);var snapshot=m.snapshot();assertThrows(UnsupportedOperationException.class,()->snapshot.timings().clear());assertThrows(UnsupportedOperationException.class,()->snapshot.outcomes().clear());assertThrows(UnsupportedOperationException.class,()->snapshot.timings().getFirst().buckets().clear());assertThrows(UnsupportedOperationException.class,()->PhoneTelemetry.lines(snapshot).clear());assertFalse(snapshot.toString().contains("question"));assertFalse(snapshot.toString().contains("session"));}
    @Test void aFlowCanOnlyBeClaimedOnceByItsMetricsOwner(){var first=new PhoneTelemetry();var second=new PhoneTelemetry();var flow=first.begin();assertTrue(first.owns(flow));assertFalse(second.owns(flow));assertTrue(flow.claim());assertFalse(flow.claim());flow.complete(PhoneTelemetry.Outcome.CANCELLED);assertFalse(flow.claim());assertFalse(flow.active());}
    @Test void completingAnActiveStageClosesItOnceEvenUnderConcurrentCancellation()throws Exception{var m=new PhoneTelemetry();var flow=m.begin();flow.start(PhoneTelemetry.Phase.ANSWER_WAIT);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->flow.complete(PhoneTelemetry.Outcome.CANCELLED));var b=pool.submit(()->flow.complete(PhoneTelemetry.Outcome.ACCEPTED));a.get();b.get();}finally{pool.shutdownNow();}var snapshot=m.snapshot();assertEquals(1,phase(snapshot,PhoneTelemetry.Phase.TOTAL).completed());assertEquals(1,phase(snapshot,PhoneTelemetry.Phase.ANSWER_WAIT).completed());assertEquals(1,snapshot.outcomes().values().stream().mapToLong(Long::longValue).sum());}
    @Test void chatSuccessAndCacheSuccessWaitForValidationAndUseSeparateOutcomes(){
        var m=new PhoneTelemetry();var validation=new CompletableFuture<Boolean>();var chat=new PhoneChat(LocalAssistant.mock(),Runnable::run,m);var work=chat.submit("일반 질문","","none",()->true,()->validation);assertTrue(chat.busy());var during=m.snapshot();assertEquals(1,phase(during,PhoneTelemetry.Phase.VALIDATION).active());assertEquals(0,during.outcomes().get(PhoneTelemetry.Outcome.ACCEPTED));validation.complete(true);work.toCompletableFuture().join();assertEquals(1,m.snapshot().outcomes().get(PhoneTelemetry.Outcome.ACCEPTED));
        chat.includeHistory(false);chat.submit("캐시 질문").toCompletableFuture().join();chat.submit("캐시 질문").toCompletableFuture().join();assertEquals(1,m.snapshot().outcomes().get(PhoneTelemetry.Outcome.CACHED));assertEquals(3,phase(m.snapshot(),PhoneTelemetry.Phase.TOTAL).completed());
    }
    @Test void rejectedCachedResponseNeverBecomesACachedAcceptance(){var m=new PhoneTelemetry();var chat=new PhoneChat(LocalAssistant.mock(),Runnable::run,m);chat.includeHistory(false);chat.submit("캐시 질문").toCompletableFuture().join();assertTrue(chat.submit("캐시 질문","","none",()->true,()->CompletableFuture.completedFuture(false)).toCompletableFuture().isCompletedExceptionally());assertEquals(0,m.snapshot().outcomes().get(PhoneTelemetry.Outcome.CACHED));assertEquals(1,m.snapshot().outcomes().get(PhoneTelemetry.Outcome.VALIDATION_FAILED));assertEquals(0,chat.cacheStats().entries());assertEquals("캐시 질문",chat.draft());}
    @Test void cancellationAndClosePreserveDraftAndRejectLateResponsesWithoutLeakingActiveCounts(){for(boolean close:List.of(false,true)){var m=new PhoneTelemetry();var source=new CompletableFuture<String>();var chat=new PhoneChat(q->source,Runnable::run,m);var result=chat.submit("질문");if(close)chat.close();else chat.cancel();source.complete("늦은 응답");assertTrue(result.toCompletableFuture().isCancelled());assertEquals(1,m.snapshot().outcomes().get(close?PhoneTelemetry.Outcome.CLOSED:PhoneTelemetry.Outcome.CANCELLED));assertEquals(0,phase(m.snapshot(),PhoneTelemetry.Phase.TOTAL).active());assertTrue(chat.history().isEmpty());}}
    @Test void busyInputAndStaleRequestsAreNotCountedAsAcceptedOrBackendSuccess(){var m=new PhoneTelemetry();var source=new CompletableFuture<String>();var chat=new PhoneChat(q->source,Runnable::run,m);chat.submit("진행 중");assertTrue(chat.submit("두 번째").toCompletableFuture().isCompletedExceptionally());assertEquals(1,m.snapshot().outcomes().get(PhoneTelemetry.Outcome.BUSY));chat.cancel();assertTrue(chat.submit("").toCompletableFuture().isCompletedExceptionally());assertEquals(1,m.snapshot().outcomes().get(PhoneTelemetry.Outcome.INPUT_REJECTED));assertTrue(chat.submit("오래된 자료","","none",()->false).toCompletableFuture().isCompletedExceptionally());assertEquals(1,m.snapshot().outcomes().get(PhoneTelemetry.Outcome.STALE));assertEquals(0,m.snapshot().outcomes().get(PhoneTelemetry.Outcome.ACCEPTED));}
    @Test void malformedReplyAndBackendOverloadHaveDifferentOutcomes(){for(var reason:List.of(AssistantFailure.Reason.INVALID_REFERENCE,AssistantFailure.Reason.BUSY,AssistantFailure.Reason.TIMEOUT)){var m=new PhoneTelemetry();var chat=new PhoneChat(q->CompletableFuture.failedFuture(new AssistantFailure(reason)),Runnable::run,m);assertTrue(chat.submit("질문").toCompletableFuture().isCompletedExceptionally());assertEquals(1,m.snapshot().outcomes().get(reason==AssistantFailure.Reason.BUSY?PhoneTelemetry.Outcome.BUSY:reason==AssistantFailure.Reason.INVALID_REFERENCE?PhoneTelemetry.Outcome.ANSWER_REJECTED:PhoneTelemetry.Outcome.BACKEND_FAILED));}}
    @Test void opaquePreviewAndExternalPreflightShareTheSameSingleTotal(){var m=new PhoneTelemetry();var chat=new PhoneChat(LocalAssistant.mock(),Runnable::run,m);var plan=PhoneGroundedFollowupTest.plan();var shown=chat.previewGrounded(plan);var flow=m.begin();flow.start(PhoneTelemetry.Phase.PREFLIGHT);flow.finish(PhoneTelemetry.Phase.PREFLIGHT);chat.submitGroundedPreview(shown,plan,()->true,()->CompletableFuture.completedFuture(true),flow).toCompletableFuture().join();assertEquals(1,phase(m.snapshot(),PhoneTelemetry.Phase.TOTAL).started());assertEquals(1,phase(m.snapshot(),PhoneTelemetry.Phase.PREFLIGHT).completed());assertEquals(1,m.snapshot().outcomes().get(PhoneTelemetry.Outcome.ACCEPTED));}
    @Test void anAlreadyClaimedFlowCannotCloseOrStealAnotherChatsActiveAttempt(){var metrics=new PhoneTelemetry();var answer=new CompletableFuture<String>();var first=new PhoneChat(q->answer,Runnable::run,metrics);var other=new PhoneChat(LocalAssistant.mock(),Runnable::run,metrics);var plan=PhoneGroundedFollowupTest.plan();var flow=metrics.begin();var pending=first.submitGroundedPreview(first.previewGrounded(plan),plan,()->true,()->CompletableFuture.completedFuture(true),flow);assertThrows(IllegalStateException.class,()->other.submitGroundedPreview(other.previewGrounded(plan),plan,()->true,()->CompletableFuture.completedFuture(true),flow));assertTrue(flow.active());answer.complete("판자 [자료 1]");pending.toCompletableFuture().join();assertEquals(1,phase(metrics.snapshot(),PhoneTelemetry.Phase.TOTAL).completed());assertEquals(1,metrics.snapshot().outcomes().get(PhoneTelemetry.Outcome.ACCEPTED));}
    @Test void stalePreviewClosesOnlyItsOwnAttemptWithoutCallingBackend(){var calls=new AtomicInteger();var m=new PhoneTelemetry();var chat=new PhoneChat(q->{calls.incrementAndGet();return CompletableFuture.completedFuture("응답");},Runnable::run,m);var plan=PhoneGroundedFollowupTest.plan();var shown=chat.previewGrounded(plan);chat.includeHistory(false);assertTrue(chat.submitGroundedPreview(shown,plan,()->true,()->CompletableFuture.completedFuture(true)).toCompletableFuture().isCompletedExceptionally());assertEquals(0,calls.get());assertEquals(1,m.snapshot().outcomes().get(PhoneTelemetry.Outcome.PREVIEW_REJECTED));assertEquals(0,phase(m.snapshot(),PhoneTelemetry.Phase.TOTAL).active());}
    @Test void consoleSnapshotReadsNeverPrepareGenerateOrExposeSensitiveData(){var calls=new AtomicInteger();var reads=new AtomicInteger();var output=new ArrayList<String>();var metrics=new PhoneTelemetry();var service=new MeasuredAssistant(q->{calls.incrementAndGet();return CompletableFuture.completedFuture("secret_question");});AssistantConsole.execute(false,new String[]{"status"},"mock",service,()->{reads.incrementAndGet();return metrics.snapshot();},Runnable::run,()->true,output::add);assertEquals(0,reads.get());AssistantConsole.execute(true,new String[]{"bad"},"mock",service,()->{reads.incrementAndGet();return metrics.snapshot();},Runnable::run,()->true,output::add);assertEquals(0,reads.get());AssistantConsole.execute(true,new String[]{"status"},"mock",service,()->{reads.incrementAndGet();return metrics.snapshot();},Runnable::run,()->true,output::add);assertEquals(1,reads.get());assertEquals(0,calls.get());assertTrue(String.join("\n",output).contains("서버 수용"));assertFalse(String.join("\n",output).contains("secret_question"));service.close();}
}
